// Seed line items (qty, unit price in cents, tax rate). One item per row.
const items = [
  { sku: 'A-100', description: 'Widget',      qty: 3, unitCents: 1299, taxRate: 0.20 },
  { sku: 'B-220', description: 'Gadget',      qty: 1, unitCents: 4999, taxRate: 0.20 },
  { sku: 'C-330', description: 'Sticker pack', qty: 10, unitCents: 199, taxRate: 0.00 }
];
return items.map((i) => ({ json: i }));

// Compute per-line and invoice totals from the valid line items. Pure compute.
const lines = $input.all().map((i) => i.json);
let subtotal = 0, tax = 0;
const detailed = lines.map((l) => {
  const lineSub = l.qty * l.unitCents;
  const lineTax = Math.round(lineSub * (l.taxRate || 0));
  subtotal += lineSub;
  tax += lineTax;
  return {
    sku: l.sku,
    description: l.description,
    qty: l.qty,
    lineSubtotal: (lineSub / 100).toFixed(2),
    lineTax: (lineTax / 100).toFixed(2),
    lineTotal: ((lineSub + lineTax) / 100).toFixed(2),
  };
});
const total = subtotal + tax;
return [{ json: {
  currency: 'USD',
  lines: detailed,
  subtotal: (subtotal / 100).toFixed(2),
  tax: (tax / 100).toFixed(2),
  total: (total / 100).toFixed(2),
} }];
